-- WP15: governed, recipient-specific masked bank disclosure on directional MESH relationships.
BEGIN;
DO $$ BEGIN IF current_database()<>'athyper_mesh' THEN RAISE EXCEPTION 'WP15 MESH bank disclosure must target athyper_mesh'; END IF; END $$;

ALTER DOMAIN mesh.bank_disclosure_status_d DROP CONSTRAINT bank_disclosure_status_d_check;
ALTER DOMAIN mesh.bank_disclosure_status_d ADD CONSTRAINT bank_disclosure_status_d_check CHECK(VALUE IN('pending_approval','active','rejected','expired','revoked','superseded'));

CREATE TABLE snapshot.bank_account_disclosure(
 id uuid NOT NULL DEFAULT shared.uuidv7(),owner_tenant_id uuid NOT NULL,recipient_tenant_id uuid NOT NULL,disclosure_id uuid NOT NULL,disclosure_version integer NOT NULL,
 schema_code text NOT NULL DEFAULT 'mesh.bank_account_disclosure',schema_version integer NOT NULL DEFAULT 1,field_set_code text NOT NULL DEFAULT 'masked_retrieval_v1',payload_json jsonb NOT NULL,payload_hash text NOT NULL,captured_at timestamptz NOT NULL DEFAULT clock_timestamp(),captured_by uuid NOT NULL,
 CONSTRAINT bank_account_disclosure_snapshot_pkey PRIMARY KEY(id),CONSTRAINT bank_account_disclosure_snapshot_owner_id_uq UNIQUE(owner_tenant_id,id),CONSTRAINT bank_account_disclosure_snapshot_version_uq UNIQUE(owner_tenant_id,disclosure_id,disclosure_version),
 CONSTRAINT bank_account_disclosure_snapshot_version_chk CHECK(disclosure_version>=1 AND schema_version=1),CONSTRAINT bank_account_disclosure_snapshot_field_chk CHECK(field_set_code='masked_retrieval_v1'),CONSTRAINT bank_account_disclosure_snapshot_payload_chk CHECK(jsonb_typeof(payload_json)='object' AND pg_column_size(payload_json)<=32768),CONSTRAINT bank_account_disclosure_snapshot_hash_chk CHECK(payload_hash~'^[a-f0-9]{64}$'),
 CONSTRAINT bank_account_disclosure_snapshot_owner_fk FOREIGN KEY(owner_tenant_id) REFERENCES master.tenant(id),CONSTRAINT bank_account_disclosure_snapshot_recipient_fk FOREIGN KEY(recipient_tenant_id) REFERENCES master.tenant(id),CONSTRAINT bank_account_disclosure_snapshot_actor_fk FOREIGN KEY(owner_tenant_id,captured_by) REFERENCES master.principal(tenant_id,id)
);

ALTER TABLE mesh.bank_account_disclosure ADD COLUMN disclosure_version integer NOT NULL DEFAULT 1,ADD COLUMN snapshot_id uuid,ADD COLUMN payload_hash text,ADD COLUMN secure_retrieval_reference text,ADD COLUMN idempotency_key text,ADD COLUMN decision_fingerprint text,ADD COLUMN approved_at timestamptz,ADD COLUMN approved_by uuid;

INSERT INTO snapshot.bank_account_disclosure(owner_tenant_id,recipient_tenant_id,disclosure_id,disclosure_version,payload_json,payload_hash,captured_by)
SELECT disclosure.owner_tenant_id,disclosure.recipient_tenant_id,disclosure.id,1,payload.value,encode(digest(payload.value::text,'sha256'),'hex'),disclosure.disclosed_by
FROM mesh.bank_account_disclosure disclosure JOIN mesh.bank_account account ON account.tenant_id=disclosure.owner_tenant_id AND account.id=disclosure.bank_account_id
CROSS JOIN LATERAL(SELECT jsonb_build_object('schemaCode','mesh.bank_account_disclosure','schemaVersion',1,'fieldSetCode','masked_retrieval_v1','disclosureId',disclosure.id,'purpose',disclosure.purpose,'bankAccount',jsonb_build_object('accountHolderName',account.account_holder_name,'accountIdType',account.account_id_type,'accountLast4',account.account_last4,'currencyCode',account.currency_code,'bankName',COALESCE(account.bank_name_override,party.name),'bankCountryCode',COALESCE(account.bank_country_override,party.country_code),'bic',COALESCE(account.bic_override,party.bic),'accountFingerprint',encode(digest(account.account_id_type::text||':'||account.account_id_value,'sha256'),'hex')),'secureRetrievalReference','legacy://unavailable/'||disclosure.id::text) value FROM mesh.bank_party party WHERE party.tenant_id=account.tenant_id AND party.id=account.bank_party_id UNION ALL SELECT jsonb_build_object('schemaCode','mesh.bank_account_disclosure','schemaVersion',1,'fieldSetCode','masked_retrieval_v1','disclosureId',disclosure.id,'purpose',disclosure.purpose,'bankAccount',jsonb_build_object('accountHolderName',account.account_holder_name,'accountIdType',account.account_id_type,'accountLast4',account.account_last4,'currencyCode',account.currency_code,'bankName',account.bank_name_override,'bankCountryCode',account.bank_country_override,'bic',account.bic_override,'accountFingerprint',encode(digest(account.account_id_type::text||':'||account.account_id_value,'sha256'),'hex')),'secureRetrievalReference','legacy://unavailable/'||disclosure.id::text) WHERE account.bank_party_id IS NULL LIMIT 1)payload;

UPDATE mesh.bank_account_disclosure disclosure SET snapshot_id=snapshot.id,payload_hash=snapshot.payload_hash,secure_retrieval_reference='legacy://unavailable/'||disclosure.id::text,idempotency_key='legacy-disclosure-'||disclosure.id::text,decision_fingerprint=encode(digest(disclosure.id::text||':'||snapshot.payload_hash,'sha256'),'hex'),approved_at=disclosure.disclosed_at,approved_by=disclosure.disclosed_by FROM snapshot.bank_account_disclosure snapshot WHERE snapshot.owner_tenant_id=disclosure.owner_tenant_id AND snapshot.disclosure_id=disclosure.id;

ALTER TABLE mesh.bank_account_disclosure ALTER COLUMN idempotency_key SET NOT NULL,ALTER COLUMN status SET DEFAULT 'pending_approval',
 ADD CONSTRAINT bank_account_disclosure_snapshot_fk FOREIGN KEY(owner_tenant_id,snapshot_id) REFERENCES snapshot.bank_account_disclosure(owner_tenant_id,id),ADD CONSTRAINT bank_account_disclosure_approved_by_fk FOREIGN KEY(owner_tenant_id,approved_by) REFERENCES master.principal(tenant_id,id),
 ADD CONSTRAINT bank_account_disclosure_version_chk CHECK(disclosure_version>=1),ADD CONSTRAINT bank_account_disclosure_hash_chk CHECK(payload_hash IS NULL OR payload_hash~'^[a-f0-9]{64}$'),ADD CONSTRAINT bank_account_disclosure_idempotency_chk CHECK(btrim(idempotency_key)=idempotency_key AND length(idempotency_key) BETWEEN 8 AND 200),
 ADD CONSTRAINT bank_account_disclosure_decision_chk CHECK((status='pending_approval' AND snapshot_id IS NULL AND payload_hash IS NULL AND secure_retrieval_reference IS NULL AND decision_fingerprint IS NULL AND approved_at IS NULL AND approved_by IS NULL) OR(status='rejected' AND snapshot_id IS NULL AND payload_hash IS NULL AND secure_retrieval_reference IS NULL AND decision_fingerprint~'^[a-f0-9]{64}$' AND approved_at IS NULL AND approved_by IS NULL)OR(status IN('active','expired','revoked','superseded') AND snapshot_id IS NOT NULL AND payload_hash~'^[a-f0-9]{64}$' AND nullif(btrim(secure_retrieval_reference),'') IS NOT NULL AND decision_fingerprint~'^[a-f0-9]{64}$' AND approved_at IS NOT NULL AND approved_by IS NOT NULL));
CREATE UNIQUE INDEX bank_account_disclosure_idempotency_uq ON mesh.bank_account_disclosure(owner_tenant_id,idempotency_key);

CREATE TABLE mesh.bank_account_disclosure_event(id uuid NOT NULL DEFAULT shared.uuidv7(),owner_tenant_id uuid NOT NULL,recipient_tenant_id uuid NOT NULL,disclosure_id uuid NOT NULL,lifecycle_version integer NOT NULL,event_kind text NOT NULL,reason text,decision_fingerprint text NOT NULL,idempotency_key text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),recorded_by uuid NOT NULL,CONSTRAINT bank_account_disclosure_event_pkey PRIMARY KEY(id),CONSTRAINT bank_account_disclosure_event_version_uq UNIQUE(owner_tenant_id,disclosure_id,lifecycle_version),CONSTRAINT bank_account_disclosure_event_idempotency_uq UNIQUE(owner_tenant_id,idempotency_key),CONSTRAINT bank_account_disclosure_event_kind_chk CHECK(event_kind IN('approved','rejected','revoked','superseded','expired')),CONSTRAINT bank_account_disclosure_event_version_chk CHECK(lifecycle_version>=1),CONSTRAINT bank_account_disclosure_event_reason_chk CHECK((event_kind='approved' AND reason IS NULL)OR(event_kind<>'approved' AND nullif(btrim(reason),'') IS NOT NULL)),CONSTRAINT bank_account_disclosure_event_fingerprint_chk CHECK(decision_fingerprint~'^[a-f0-9]{64}$'),CONSTRAINT bank_account_disclosure_event_key_chk CHECK(length(idempotency_key) BETWEEN 8 AND 200),CONSTRAINT bank_account_disclosure_event_owner_fk FOREIGN KEY(owner_tenant_id) REFERENCES master.tenant(id),CONSTRAINT bank_account_disclosure_event_recipient_fk FOREIGN KEY(recipient_tenant_id) REFERENCES master.tenant(id),CONSTRAINT bank_account_disclosure_event_disclosure_fk FOREIGN KEY(disclosure_id) REFERENCES mesh.bank_account_disclosure(id),CONSTRAINT bank_account_disclosure_event_actor_fk FOREIGN KEY(owner_tenant_id,recorded_by) REFERENCES master.principal(tenant_id,id));

CREATE OR REPLACE FUNCTION snapshot.trg_reject_bank_disclosure_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'snapshot.bank_account_disclosure is immutable' USING ERRCODE='integrity_constraint_violation'; END $$;
CREATE TRIGGER trg_bank_account_disclosure_snapshot_immutable BEFORE UPDATE OR DELETE ON snapshot.bank_account_disclosure FOR EACH ROW EXECUTE FUNCTION snapshot.trg_reject_bank_disclosure_mutation();
CREATE OR REPLACE FUNCTION mesh.trg_reject_bank_disclosure_event_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'Bank disclosure lifecycle events are append-only' USING ERRCODE='integrity_constraint_violation'; END $$;
CREATE TRIGGER trg_bank_account_disclosure_event_immutable BEFORE UPDATE OR DELETE ON mesh.bank_account_disclosure_event FOR EACH ROW EXECUTE FUNCTION mesh.trg_reject_bank_disclosure_event_mutation();

CREATE OR REPLACE FUNCTION mesh.trg_guard_bank_disclosure() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,mesh AS $$ BEGIN
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.owner_tenant_id IS DISTINCT FROM OLD.owner_tenant_id OR NEW.owner_account_id IS DISTINCT FROM OLD.owner_account_id OR NEW.bank_account_id IS DISTINCT FROM OLD.bank_account_id OR NEW.network_relationship_id IS DISTINCT FROM OLD.network_relationship_id OR NEW.recipient_tenant_id IS DISTINCT FROM OLD.recipient_tenant_id OR NEW.recipient_account_id IS DISTINCT FROM OLD.recipient_account_id OR NEW.purpose IS DISTINCT FROM OLD.purpose OR NEW.disclosed_at IS DISTINCT FROM OLD.disclosed_at OR NEW.disclosed_by IS DISTINCT FROM OLD.disclosed_by OR NEW.disclosure_version IS DISTINCT FROM OLD.disclosure_version OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN RAISE EXCEPTION 'Mesh bank-disclosure coordinates and evidence are immutable' USING ERRCODE='check_violation'; END IF;
 IF OLD.status IN('expired','revoked','superseded','rejected') AND NEW.status IS DISTINCT FROM OLD.status THEN RAISE EXCEPTION 'Terminal bank disclosure cannot transition' USING ERRCODE='check_violation'; END IF;
 IF OLD.decision_fingerprint IS NOT NULL AND (NEW.snapshot_id,NEW.payload_hash,NEW.secure_retrieval_reference,NEW.decision_fingerprint,NEW.approved_at,NEW.approved_by) IS DISTINCT FROM (OLD.snapshot_id,OLD.payload_hash,OLD.secure_retrieval_reference,OLD.decision_fingerprint,OLD.approved_at,OLD.approved_by) THEN RAISE EXCEPTION 'Bank disclosure approval evidence is immutable' USING ERRCODE='check_violation'; END IF;
 IF NEW.approved_by IS NOT NULL AND NEW.approved_by=NEW.disclosed_by THEN RAISE EXCEPTION 'Bank disclosure requires independent approval' USING ERRCODE='insufficient_privilege'; END IF;
 IF NEW.status='revoked' AND(NEW.revoked_at IS NULL OR NEW.revoked_by IS NULL) THEN RAISE EXCEPTION 'Revocation requires evidence' USING ERRCODE='check_violation'; END IF; RETURN NEW; END $$;

ALTER TABLE snapshot.bank_account_disclosure ENABLE ROW LEVEL SECURITY;ALTER TABLE snapshot.bank_account_disclosure FORCE ROW LEVEL SECURITY;CREATE POLICY bank_disclosure_snapshot_participant_read ON snapshot.bank_account_disclosure FOR SELECT USING(shared.current_tenant_id_soft() IN(owner_tenant_id,recipient_tenant_id));CREATE POLICY bank_disclosure_snapshot_owner_insert ON snapshot.bank_account_disclosure FOR INSERT WITH CHECK(owner_tenant_id=shared.current_tenant_id());CREATE POLICY seed_write ON snapshot.bank_account_disclosure FOR ALL TO CURRENT_USER USING(true) WITH CHECK(true);
ALTER TABLE mesh.bank_account_disclosure_event ENABLE ROW LEVEL SECURITY;ALTER TABLE mesh.bank_account_disclosure_event FORCE ROW LEVEL SECURITY;CREATE POLICY participant_read ON mesh.bank_account_disclosure_event FOR SELECT USING(owner_tenant_id=shared.current_tenant_id_soft() OR recipient_tenant_id=shared.current_tenant_id_soft());CREATE POLICY owner_insert ON mesh.bank_account_disclosure_event FOR INSERT WITH CHECK(owner_tenant_id=shared.current_tenant_id());CREATE POLICY seed_write ON mesh.bank_account_disclosure_event FOR ALL TO CURRENT_USER USING(true) WITH CHECK(true);

INSERT INTO authz.permission(id,canonical_code,permission_kind,module_id,risk_tier,requires_mfa,requires_sod,is_shareable,is_delegable,is_overridable,metadata,status,created_by)
SELECT definition.id,definition.code,'entity_operation',module.id,definition.risk::authz.risk_tier_d,definition.mfa,definition.sod,false,false,false,'{"_seed":{"pack":"mesh.bank-disclosure","version":"1.0.0"}}','published','00000000-0000-0000-0000-000000000000' FROM control.module module CROSS JOIN(VALUES('0b5369ec-1c15-55c8-8d73-d733f1d1b2da'::uuid,'mesh.bank_disclosure.request','high',false,true),('da8d53ba-3de8-5294-8b19-62b7eed3b705'::uuid,'mesh.bank_disclosure.decide','critical',true,true),('2fb59982-bb4b-589d-9690-ce10e7d0565a'::uuid,'mesh.bank_disclosure.read','high',true,false),('4bdf83af-d931-51ee-8755-d3634979a518'::uuid,'mesh.bank_disclosure.revoke','critical',true,true))definition(id,code,risk,mfa,sod) WHERE module.code='fnd' ON CONFLICT(canonical_code) DO UPDATE SET risk_tier=EXCLUDED.risk_tier,requires_mfa=EXCLUDED.requires_mfa,requires_sod=EXCLUDED.requires_sod,status='published';
INSERT INTO authz.permission_scope_kind(permission_id,scope_kind,propagation_mode,status,created_by) SELECT id,'network_relationship','exact','active','00000000-0000-0000-0000-000000000000' FROM authz.permission WHERE canonical_code LIKE 'mesh.bank_disclosure.%' ON CONFLICT(permission_id,scope_kind,propagation_mode) DO UPDATE SET status='active';

DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='athyperapp') THEN GRANT SELECT,INSERT,UPDATE ON mesh.bank_account_disclosure TO athyperapp;GRANT SELECT,INSERT ON mesh.bank_account_disclosure_event,snapshot.bank_account_disclosure TO athyperapp; END IF; END $$;
COMMIT;
